// 시스템 상태 체크 시뮬레이션
const inputData = $input.all()[0].json;

// 현재 시간
const now = new Date();
const timestamp = now.toISOString();

// 시스템 메트릭 시뮬레이션 (실제 환경에서는 실제 메트릭 수집)
const metrics = {
  cpu: {
    usage: Math.random() * 100,
    cores: 8,
    temperature: 45 + Math.random() * 30
  },
  memory: {
    total: 16384, // MB
    used: Math.random() * 12000 + 2000,
    available: 0
  },
  disk: {
    total: 512000, // MB  
    used: Math.random() * 400000 + 50000,
    available: 0
  },
  network: {
    inbound: Math.random() * 1000, // Mbps
    outbound: Math.random() * 500,
    latency: Math.random() * 100 + 10 // ms
  },
  services: {
    database: Math.random() > 0.1 ? 'healthy' : 'warning',
    webserver: Math.random() > 0.05 ? 'healthy' : 'critical',
    api: Math.random() > 0.08 ? 'healthy' : 'warning'
  }
};

// 계산된 값들
metrics.memory.available = metrics.memory.total - metrics.memory.used;
metrics.disk.available = metrics.disk.total - metrics.disk.used;
metrics.memory.usagePercent = (metrics.memory.used / metrics.memory.total) * 100;
metrics.disk.usagePercent = (metrics.disk.used / metrics.disk.total) * 100;

return [{
  json: {
    timestamp: timestamp,
    systemMetrics: metrics,
    checkInterval: inputData.interval || '5m',
    monitoringEnabled: true
  }
}];

// 시스템 상태 분석 및 알람 레벨 결정
const data = $input.all()[0].json;
const metrics = data.systemMetrics;

// 임계값 정의
const thresholds = {
  cpu: { warning: 70, critical: 90 },
  memory: { warning: 80, critical: 95 },
  disk: { warning: 85, critical: 95 },
  temperature: { warning: 70, critical: 85 },
  latency: { warning: 100, critical: 200 }
};

// 알람 분석
const alerts = [];
let overallStatus = 'healthy';
let severityScore = 0;

// CPU 체크
if (metrics.cpu.usage > thresholds.cpu.critical) {
  alerts.push({
    type: 'CPU',
    level: 'CRITICAL',
    message: `CPU 사용률 위험 수준: ${metrics.cpu.usage.toFixed(1)}%`,
    value: metrics.cpu.usage,
    threshold: thresholds.cpu.critical
  });
  severityScore += 3;
} else if (metrics.cpu.usage > thresholds.cpu.warning) {
  alerts.push({
    type: 'CPU',
    level: 'WARNING',
    message: `CPU 사용률 주의 수준: ${metrics.cpu.usage.toFixed(1)}%`,
    value: metrics.cpu.usage,
    threshold: thresholds.cpu.warning
  });
  severityScore += 1;
}

// 메모리 체크
if (metrics.memory.usagePercent > thresholds.memory.critical) {
  alerts.push({
    type: 'MEMORY',
    level: 'CRITICAL',
    message: `메모리 사용률 위험 수준: ${metrics.memory.usagePercent.toFixed(1)}%`,
    value: metrics.memory.usagePercent,
    threshold: thresholds.memory.critical
  });
  severityScore += 3;
} else if (metrics.memory.usagePercent > thresholds.memory.warning) {
  alerts.push({
    type: 'MEMORY',
    level: 'WARNING',
    message: `메모리 사용률 주의 수준: ${metrics.memory.usagePercent.toFixed(1)}%`,
    value: metrics.memory.usagePercent,
    threshold: thresholds.memory.warning
  });
  severityScore += 1;
}

// 디스크 체크
if (metrics.disk.usagePercent > thresholds.disk.critical) {
  alerts.push({
    type: 'DISK',
    level: 'CRITICAL',
    message: `디스크 사용률 위험 수준: ${metrics.disk.usagePercent.toFixed(1)}%`,
    value: metrics.disk.usagePercent,
    threshold: thresholds.disk.critical
  });
  severityScore += 3;
} else if (metrics.disk.usagePercent > thresholds.disk.warning) {
  alerts.push({
    type: 'DISK',
    level: 'WARNING',
    message: `디스크 사용률 주의 수준: ${metrics.disk.usagePercent.toFixed(1)}%`,
    value: metrics.disk.usagePercent,
    threshold: thresholds.disk.warning
  });
  severityScore += 1;
}

// 서비스 상태 체크
Object.entries(metrics.services).forEach(([service, status]) => {
  if (status === 'critical') {
    alerts.push({
      type: 'SERVICE',
      level: 'CRITICAL',
      message: `서비스 ${service} 중단 상태`,
      service: service,
      status: status
    });
    severityScore += 3;
  } else if (status === 'warning') {
    alerts.push({
      type: 'SERVICE',
      level: 'WARNING',
      message: `서비스 ${service} 주의 상태`,
      service: service,
      status: status
    });
    severityScore += 1;
  }
});

// 전체 상태 결정
if (severityScore >= 6) {
  overallStatus = 'critical';
} else if (severityScore >= 3) {
  overallStatus = 'warning';
} else if (alerts.length > 0) {
  overallStatus = 'degraded';
}

return [{
  json: {
    timestamp: data.timestamp,
    systemMetrics: metrics,
    analysis: {
      overallStatus: overallStatus,
      severityScore: severityScore,
      alertCount: alerts.length,
      alerts: alerts,
      thresholds: thresholds
    },
    needsNotification: severityScore > 0
  }
}];

// 알림 메시지 생성 및 전송 시뮬레이션
const data = $input.all()[0].json;
const analysis = data.analysis;

// 알림 메시지 구성
const alertMessage = {
  subject: `🚨 시스템 모니터링 알림 - ${analysis.overallStatus.toUpperCase()}`,
  timestamp: new Date().toISOString(),
  severity: analysis.overallStatus,
  summary: {
    status: analysis.overallStatus,
    alertCount: analysis.alertCount,
    severityScore: analysis.severityScore
  },
  details: analysis.alerts.map(alert => ({
    type: alert.type,
    level: alert.level,
    message: alert.message,
    ...(alert.value && { value: alert.value.toFixed(1) }),
    ...(alert.threshold && { threshold: alert.threshold })
  })),
  recommendations: [],
  systemSnapshot: {
    cpu: `${data.systemMetrics.cpu.usage.toFixed(1)}%`,
    memory: `${data.systemMetrics.memory.usagePercent.toFixed(1)}%`,
    disk: `${data.systemMetrics.disk.usagePercent.toFixed(1)}%`,
    services: data.systemMetrics.services
  }
};

// 권장사항 생성
analysis.alerts.forEach(alert => {
  switch(alert.type) {
    case 'CPU':
      alertMessage.recommendations.push('프로세스 점검 및 불필요한 작업 종료');
      break;
    case 'MEMORY':
      alertMessage.recommendations.push('메모리 누수 점검 및 캐시 정리');
      break;
    case 'DISK':
      alertMessage.recommendations.push('불필요한 파일 정리 및 로그 로테이션');
      break;
    case 'SERVICE':
      alertMessage.recommendations.push(`${alert.service} 서비스 재시작 검토`);
      break;
  }
});

// 중복 제거
alertMessage.recommendations = [...new Set(alertMessage.recommendations)];

return [{
  json: {
    notification: alertMessage,
    sentTo: ['admin@company.com', 'devops@company.com'],
    notificationMethod: ['email', 'slack'],
    escalation: analysis.severityScore >= 6 ? 'immediate' : 'normal',
    followUpRequired: analysis.overallStatus === 'critical'
  }
}];

// 정상 상태 보고서 생성
const data = $input.all()[0].json;

const healthReport = {
  timestamp: new Date().toISOString(),
  status: 'ALL_SYSTEMS_OPERATIONAL',
  summary: {
    overallHealth: data.analysis.overallStatus,
    monitorsChecked: 7,
    issuesFound: 0,
    lastCheck: data.timestamp
  },
  metrics: {
    cpu: `${data.systemMetrics.cpu.usage.toFixed(1)}%`,
    memory: `${data.systemMetrics.memory.usagePercent.toFixed(1)}%`,
    disk: `${data.systemMetrics.disk.usagePercent.toFixed(1)}%`,
    network: `${data.systemMetrics.network.latency.toFixed(0)}ms`,
    services: Object.entries(data.systemMetrics.services).filter(([_, status]) => status === 'healthy').length
  },
  nextCheck: new Date(Date.now() + 5 * 60 * 1000).toISOString() // 5분 후
};

return [{
  json: {
    healthReport: healthReport,
    logLevel: 'INFO',
    dashboardUpdate: true
  }
}];

// 모니터링 결과 통합 및 최종 응답 생성
const allInputs = $input.all();
let finalReport;

if (allInputs.length > 0) {
  const firstInput = allInputs[0].json;

  // 알림이 발송된 경우
  if (firstInput.notification) {
    finalReport = {
      monitoringResult: 'ALERTS_GENERATED',
      timestamp: new Date().toISOString(),
      alertsTriggered: true,
      notification: {
        sent: true,
        severity: firstInput.notification.severity,
        alertCount: firstInput.notification.summary.alertCount,
        recipients: firstInput.sentTo,
        escalation: firstInput.escalation
      },
      summary: firstInput.notification.systemSnapshot
    };
  } else {
    // 정상 상태 보고인 경우
    finalReport = {
      monitoringResult: 'SYSTEM_HEALTHY',
      timestamp: new Date().toISOString(),
      alertsTriggered: false,
      healthReport: firstInput.healthReport,
      summary: firstInput.healthReport.metrics
    };
  }
} else {
  // 기본 응답
  finalReport = {
    monitoringResult: 'MONITORING_COMPLETED',
    timestamp: new Date().toISOString(),
    status: 'success'
  };
}

// 공통 메타데이터 추가
finalReport.workflow = {
  name: 'System Monitoring',
  version: '1.0.0',
  executionId: Math.random().toString(36).substr(2, 9),
  nextExecution: new Date(Date.now() + 5 * 60 * 1000).toISOString()
};

return [{ json: finalReport }];
